} elseif ($isC011EC73) {
    $C70RetainedSurvivors = if ($C71Case -in @("15matchlow", "15matchhigh", "baseline15", "15above", "15adjacentbelow", "15mid", "15mid2", "15mid3", "15mid4", "15mid5", "15mid6", "15mid7", "15mid8", "15mid9")) { 15 } else { 16 }
}
