                        "c011ec53-exited-before-completion-marker"
                    } else {
                        "c011ec53-timeout-before-completion-marker"
                    }
                } elseif ($isC011EC49) {
                    $earlyFailure = if ($qemuProcess.HasExited) {
                        "c011ec49-exited-before-completion-marker"
                    } else {
                        "c011ec49-timeout-before-completion-marker"
                    }
                } elseif (($isFirstNonNullRoot -or $isFirstRootCallbackEntry) -and $failureSerial -match '\[PageFault\] Not-present violation on read \(kernel\)') {
                    $earlyFailure = "nativeaot-thread-static-startup-page-fault"
                } elseif ($isC011EC34 -and $failureSerial -match 'marker=C011EC33-LIVE') {
                    $earlyFailure = "relocation-root-scan-timeout-after-c011ec33-relocation-entry"
                } elseif ($isC011EC37 -and $failureSerial -match 'marker=C011EC37-C1-LIVE') {
                    $earlyFailure = "collection2-completion-timeout-after-c011ec37-c1-live"
                } elseif ($isC011EC36 -and $failureSerial -match 'marker=C011EC36-C1-LIVE') {
                    $earlyFailure = "collection2-same-handle-clear-timeout-after-c011ec36-preflight"
                } elseif ($isC011EC33 -and $failureSerial -match 'marker=C011EC33-LIVE') {
                    $earlyFailure = "collection1-post-weak-completion-timeout"
                } elseif ($qemuProcess.HasExited) {
                    $watchdogTriggered = $true
                    $watchdogReason = 'qemu-exited-before-completion-marker'
                    Add-QemuChronologyEvent $chronologyEvents $chronologyClock 'watchdog-condition-triggered' @{ reason=$watchdogReason }
                    throw "QEMU $name exited before the NativeAOT GC safe-stop marker."
                } else {
                    $watchdogTriggered = $true
                    $watchdogReason = 'timeout'
                    if (-not $timeoutReached) {
                        $timeoutReached = $true
                        Add-QemuChronologyEvent $chronologyEvents $chronologyClock 'timeout-reached' @{ timeoutSeconds=$TimeoutSeconds }
                    }
                    Add-QemuChronologyEvent $chronologyEvents $chronologyClock 'watchdog-condition-triggered' @{ reason=$watchdogReason }
                    throw "QEMU $name timed out after $TimeoutSeconds seconds."
                }
            }
        } finally {
            Add-QemuChronologyEvent $chronologyEvents $chronologyClock 'cleanup-initiated' @{ reason=if($completed){'safe-stop'}elseif($null -ne $earlyFailure){$earlyFailure}else{'watchdog-or-error'} }
            if ($null -ne $qemuProcess) {
                if (-not $qemuProcess.HasExited) { Stop-Process -Id $qemuProcess.Id -Force }
                try { $qemuProcess.WaitForExit() } catch { }
                if (-not $qemuExitRecorded) {
                    $qemuExitRecorded = $true
                    Add-QemuChronologyEvent $chronologyEvents $chronologyClock 'qemu-process-exit' @{ exitCode=(Get-QemuExitCode $qemuProcess); afterCleanup=$true }
                }
            }
            $qemuExitOrdinal = @($chronologyEvents | Where-Object { $_.event -eq 'qemu-process-exit' } | Select-Object -First 1 | ForEach-Object { $_.ordinal })
            $watchdogOrdinal = @($chronologyEvents | Where-Object { $_.event -eq 'watchdog-condition-triggered' } | Select-Object -First 1 | ForEach-Object { $_.ordinal })
            $qemuExitedBeforeWatchdog = $qemuExitOrdinal.Count -ne 0 -and ($watchdogOrdinal.Count -eq 0 -or $qemuExitOrdinal[0] -lt $watchdogOrdinal[0])
            [ordered]@{
                run=$name; timeoutSeconds=$TimeoutSeconds; safeStopObserved=$completed; earlyFailure=$earlyFailure
                watchdogTriggered=$watchdogTriggered; watchdogReason=$watchdogReason; timeoutReached=$timeoutReached
                qemuExitedBeforeWatchdog=$qemuExitedBeforeWatchdog; processId=if($null -ne $qemuProcess){$qemuProcess.Id}else{$null}
                exitCode=if($null -ne $qemuProcess){Get-QemuExitCode $qemuProcess}else{$null}; monitorPort=$port
                serialPath=$serialPath; monitorPath=$monitorPath; qemuDebugPath=$qemuDebugPath; chronologyPath=$chronologyPath
            } | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $oneRoot "watchdog.json") -Encoding ASCII
            [ordered]@{
                run=$name; timeoutSeconds=$TimeoutSeconds; monitorPort=$port; command=$qemuCommand
                events=@($chronologyEvents); qemuExitedBeforeWatchdog=$qemuExitedBeforeWatchdog
                exitCode=if($null -ne $qemuProcess){Get-QemuExitCode $qemuProcess}else{$null}
                firstSerialByteObserved=$firstSerialByteObserved; serialPath=$serialPath
            } | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $chronologyPath -Encoding ASCII
        }
        Require-File $serialPath "Fresh QEMU serial log"
        $serial = Get-Content -LiteralPath $serialPath -Raw
        Set-Content -LiteralPath (Join-Path $oneRoot "serial.sha256") -Value (Hash-File $serialPath) -Encoding ASCII
        $postWeakPhaseLines = @($serial -split '\r?\n' | Where-Object { $_ -match 'POST-WEAK phase=' })
        $validationText = $serial -replace '\[IRQ\] dispatch irq=00\s*', ''
        $validationText = ($validationText -creplace '(?<=[0-9])(?=[a-z])', ' ') -replace '\s+', ' '
        $validationText = $validationText -replace '\b(c\d+)\s+(ec\d+)', '$1$2'
        $validationText = $validationText -replace '\s*=\s*', '='
        $validationText = $validationText -replace '\s*-\s*', '-'
        if ($isC011EC49) {
            $c49CompleteLine = [regex]::Match(
                $validationText,
                '\[nativeaot-gc-second-collection\]\s+COMPLETE.*?marker=C011EC49(?:\s|$)').Value.Trim()
            $c49BlockedLine = [regex]::Match(
                $validationText,
                '\[nativeaot-gc-second-collection\]\s+BLOCKED.*?marker=C011EC49-BLOCKED(?:\s|$)').Value.Trim()
            $c49MarkerLine = if (-not [string]::IsNullOrWhiteSpace($c49CompleteLine)) {
                $c49CompleteLine
            } elseif (-not [string]::IsNullOrWhiteSpace($c49BlockedLine)) {
                $c49BlockedLine
            } else { $null }
            $c49OutcomeMatch = if ($null -ne $c49MarkerLine) {
                [regex]::Match($c49MarkerLine, 'outcome=(?<outcome>[ABCD])')
            } else { $null }
            $c49SemanticOutcome = if ($null -ne $c49OutcomeMatch -and $c49OutcomeMatch.Success) {
                $c49OutcomeMatch.Groups['outcome'].Value
            } else { 'D' }
            $c49SuccessLevel = switch ($c49SemanticOutcome) {
                'A' { 5 }
                'B' { 3 }
                'C' { 1 }
                default { 0 }
            }
            $runResults += [ordered]@{
                name=$name; serial=$serialPath; serialSha256=(Hash-File $serialPath)
                safeStopMarker=if ($null -ne $c49MarkerLine) { 'C011EC49' } else { 'C011EC49-TIMEOUT' }
                outcome=$c49SemanticOutcome; semanticOutcome=$c49SemanticOutcome
                successLevel=$c49SuccessLevel; harnessTerminated=$true
                markerLine=$c49MarkerLine; earlyFailure=$earlyFailure
                serialTail=if ($validationText.Length -gt 16000) { $validationText.Substring($validationText.Length - 16000) } else { $validationText }
            }
            continue
        } elseif ($isC011EC84) {
            $c84CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC84' | Where-Object { $_ -match 'marker=C011EC84\s+outcome=' })
            $c84MarkerLine = if ($c84CompleteLines.Count -ne 0) { $c84CompleteLines[-1].Trim() } else { $null }
            if ($null -eq $c84MarkerLine) { throw 'C011EC84 did not reach its exact-region probe completion marker.' }
            $c84Records = @(Get-C011EC56MarkerRecords $validationText 'C84_REGION_PROBE_RECORD')
            $c84Summaries = @(Get-C011EC56MarkerRecords $validationText 'C84_REGION_PROBE_SUMMARY')
            $c77CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC77' | Where-Object { $_ -match 'marker=C011EC77\s+outcome=C' })
            $c77SummaryLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC77-SUMMARY')
            $c76SummaryLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC76-SUMMARY')
            $c77Events = @(Get-C011EC56MarkerRecords $validationText 'C77_EVENT_ORDINAL')
            $c77Regions = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_COUNT')
            $c77Births = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_BIRTH')
            $c77Expansions = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_EXPAND')
            $c77Reclaims = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_RECLAIM')
            $c73CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC73' | Where-Object { $_ -match 'marker=C011EC73\s+outcome=' })
            $c73SummaryLines = @(Get-C011EC56MarkerRecords $validationText 'C73_SUMMARY')
            $c73PromotionLines = @(Get-C011EC56MarkerRecords $validationText 'C70_PROMOTION_OBSERVED')
            $c72CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC72' | Where-Object { $_ -match 'marker=C011EC72\s+.*successLevel=' })
            if ($c84Records.Count -ne 5 -or $c84Summaries.Count -ne 1 -or $c77CompleteLines.Count -eq 0) {
                throw 'C011EC84 required five target records, one summary, and inherited C77 completion.'
            }
            $c84LevelText = Get-MarkerField $c84MarkerLine 'successLevel'
            $c84Level = if ($null -ne $c84LevelText) { [Convert]::ToUInt32($c84LevelText.Substring(2), 16) } else { 0 }
            $runResults += [ordered]@{
                name=$name; serial=$serialPath; serialSha256=(Hash-File $serialPath)
                safeStopMarker='C011EC84'; outcome='C'; semanticOutcome='C'; successLevel=$c84Level
                harnessTerminated=$true; markerLine=$c84MarkerLine; earlyFailure=$earlyFailure
                c84CompleteLines=$c84CompleteLines; c84RecordLines=$c84Records; c84SummaryLines=$c84Summaries
                c77CompleteLines=$c77CompleteLines; c77SummaryLines=$c77SummaryLines; c77EventLines=$c77Events
                c77RegionLines=$c77Regions; c77BirthLines=$c77Births; c77ExpansionLines=$c77Expansions
                c77ReclaimLines=$c77Reclaims; c76SummaryLines=$c76SummaryLines
                c73CompleteLines=$c73CompleteLines; c73SummaryLines=$c73SummaryLines; c73PromotionLines=$c73PromotionLines; c72CompleteLines=$c72CompleteLines
                c67CompleteLines=@(Get-C011EC56MarkerRecords $validationText 'C011EC67' | Where-Object { $_ -match 'marker=C011EC67\s+outcome=' })
                serialTail=if ($validationText.Length -gt 160000) { $validationText.Substring($validationText.Length - 160000) } else { $validationText }
            }
            continue
        } elseif ($isC011EC77) {
            $c77CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC77' | Where-Object { $_ -match 'marker=C011EC77\s+outcome=C' })
            $c77MarkerLine = if ($c77CompleteLines.Count -ne 0) { $c77CompleteLines[-1].Trim() } else { $null }
            if ($null -eq $c77MarkerLine) { throw 'C011EC77 did not reach its lifecycle completion marker.' }
            $c77LevelText = Get-MarkerField $c77MarkerLine 'successLevel'
            $c77Level = if ($null -ne $c77LevelText) { [Convert]::ToUInt32($c77LevelText.Substring(2), 16) } else { 0 }
            $c76SummaryLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC76-SUMMARY')
            $c76CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC76' | Where-Object { $_ -match 'marker=C011EC76\s+outcome=' })
            $c77Events = @(Get-C011EC56MarkerRecords $validationText 'C77_EVENT_ORDINAL')
            $c77Regions = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_COUNT')
            $c77Births = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_BIRTH')
            $c77Expansions = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_EXPAND')
            $c77Reclaims = @(Get-C011EC56MarkerRecords $validationText 'C77_REGION_RECLAIM')
            $c79Records = @(Get-C011EC56MarkerRecords $validationText 'C79_CENSUS_RECORD')
            $c79Summaries = @(Get-C011EC56MarkerRecords $validationText 'C79_CENSUS_SUMMARY')
            $c79CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC79' | Where-Object { $_ -match 'marker=C011EC79 outcome=' })
            $c80Records = @(Get-C011EC56MarkerRecords $validationText 'C80_REGION_RECORD')
            $c80Summaries = @(Get-C011EC56MarkerRecords $validationText 'C80_SNAPSHOT_SUMMARY')
            $c80CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC80' | Where-Object { $_ -match 'marker=C011EC80 outcome=' })
            $c81Entries = @(Get-C011EC56MarkerRecords $validationText 'C81_BASIC_LIST_ENTRY')
            $c81Summaries = @(Get-C011EC56MarkerRecords $validationText 'C81_BASIC_LIST_SUMMARY')
            $c81CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC81' | Where-Object { $_ -match 'marker=C011EC81 outcome=' })
            $c83Records = @(Get-C011EC56MarkerRecords $validationText 'C83_BASIC_MAPPING_RECORD')
            $c83Summaries = @(Get-C011EC56MarkerRecords $validationText 'C83_BASIC_MAPPING_SUMMARY')
            $c83CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC83' | Where-Object { $_ -match 'marker=C011EC83 outcome=' })
            $c79InheritedRangeRecords = @(Get-C011EC56MarkerRecords $validationText 'C76_REGION_ELIGIBILITY')
            if ($isC011EC79 -and $c79Records.Count -eq 0 -and $c79InheritedRangeRecords.Count -ne 0) {
                # C79 intentionally has no new live range walk.  Reuse the
                # accepted C76 range-bearing records as the bounded raw input
                # for the offline analyzer.
                $c79Records = $c79InheritedRangeRecords
            }
            if ($c76SummaryLines.Count -eq 0 -or $c77Events.Count -eq 0 -or $c77Regions.Count -eq 0) {
                throw 'C011EC77 required C76 classification and C67-backed lifecycle records were absent.'
            }
            if ($isC011EC79 -and ($c79Records.Count -eq 0 -or $c79Summaries.Count -eq 0 -or $c79CompleteLines.Count -eq 0)) {
                throw 'C011EC79 required bounded range records, summaries, and completion marker were absent.'
            }
            if ($isC011EC80 -and ($c80Records.Count -eq 0 -or $c80Summaries.Count -ne 4 -or $c80CompleteLines.Count -eq 0)) {
                throw 'C011EC80 required canonical region records, four snapshot summaries, and completion marker were absent.'
            }
            if ($isC011EC83 -and ($c83Summaries.Count -eq 0 -or $c83CompleteLines.Count -eq 0)) {
                throw 'C011EC83 required a basic-to-canonical summary and completion marker.'
            }
            $runResults += [ordered]@{
                name=$name; serial=$serialPath; serialSha256=(Hash-File $serialPath)
                safeStopMarker='C011EC77'; outcome='C'; semanticOutcome='C'; successLevel=$c77Level
                harnessTerminated=$true; markerLine=$c77MarkerLine; earlyFailure=$earlyFailure
                c77CompleteLines=$c77CompleteLines; c77EventLines=$c77Events; c77RegionLines=$c77Regions
                c77BirthLines=$c77Births; c77ExpansionLines=$c77Expansions; c77ReclaimLines=$c77Reclaims
                c79RecordLines=$c79Records; c79SummaryLines=$c79Summaries; c79CompleteLines=$c79CompleteLines
                c79InheritedRangeLines=$c79InheritedRangeRecords
                c80RecordLines=$c80Records; c80SummaryLines=$c80Summaries; c80CompleteLines=$c80CompleteLines
                c81EntryLines=$c81Entries; c81SummaryLines=$c81Summaries; c81CompleteLines=$c81CompleteLines
                c83RecordLines=$c83Records; c83SummaryLines=$c83Summaries; c83CompleteLines=$c83CompleteLines
                c77PreflightLines=@(Get-C011EC56MarkerRecords $validationText 'C011EC77-PREFLIGHT')
                c76CompleteLines=$c76CompleteLines; c76SummaryLines=$c76SummaryLines
                c76EligibilityLines=@(Get-C011EC56MarkerRecords $validationText 'C76_REGION_ELIGIBILITY')
                c76InsertLines=@(Get-C011EC56MarkerRecords $validationText 'C76_BASIC_INSERT')
                c76RemoveLines=@(Get-C011EC56MarkerRecords $validationText 'C76_BASIC_REMOVE')
                c67CompleteLines=@(Get-C011EC56MarkerRecords $validationText 'C011EC67' | Where-Object { $_ -match 'marker=C011EC67\s+outcome=' })
                serialTail=if ($validationText.Length -gt 160000) { $validationText.Substring($validationText.Length - 160000) } else { $validationText }
            }
            continue
        } elseif ($isC011EC76) {
            $c76CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC76' | Where-Object { $_ -match 'marker=C011EC76\s+outcome=' })
            $c76MarkerLine = if ($c76CompleteLines.Count -ne 0) { $c76CompleteLines[-1].Trim() } else { $null }
            $c76OutcomeMatch = if ($null -ne $c76MarkerLine) { [regex]::Match($c76MarkerLine, 'outcome=(?<outcome>[ABDE])') } else { $null }
            $c76Outcome = if ($null -ne $c76OutcomeMatch -and $c76OutcomeMatch.Success) { $c76OutcomeMatch.Groups['outcome'].Value } else { 'E' }
            $c76LevelText = if ($null -ne $c76MarkerLine) { Get-MarkerField $c76MarkerLine 'successLevel' } else { $null }
            $c76Level = if ($null -ne $c76LevelText) { [Convert]::ToUInt32($c76LevelText.Substring(2), 16) } else { 0 }
            $c76SummaryLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC76-SUMMARY')
            $c76EligibilityLines = @(Get-C011EC56MarkerRecords $validationText 'C76_REGION_ELIGIBILITY')
            $c76InsertLines = @(Get-C011EC56MarkerRecords $validationText 'C76_BASIC_INSERT')
            $c76RemoveLines = @(Get-C011EC56MarkerRecords $validationText 'C76_BASIC_REMOVE')
            $c76PreflightLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC76-PREFLIGHT')
            $c73CompleteLines = @(Get-C011EC56MarkerRecords $validationText 'C011EC73' | Where-Object { $_ -match 'marker=C011EC73\s+outcome=' })
            if ($c76CompleteLines.Count -eq 0 -or $c76SummaryLines.Count -eq 0 -or $c76PreflightLines.Count -eq 0) {
