            $plannerLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+PLANNER.*?marker=C011EC49-PLANNER').Value.Trim()
            $compactLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+COMPACT.*?marker=C011EC49-COMPACT').Value.Trim()
            $sweepLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+SWEEP.*?marker=C011EC49-SWEEP').Value.Trim()
            $relocateLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+RELOCATE.*?marker=C011EC49-RELOCATE').Value.Trim()
            $doneLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+COLLECTION-DONE.*?marker=C011EC49-COLLECTION-DONE').Value.Trim()
            $restartLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+RESTART.*?marker=C011EC49-RESTART').Value.Trim()
            $resumeLine = [regex]::Match($normalized, '\[nativeaot-gc-second-collection\]\s+RESUME.*?marker=C011EC49-RESUME').Value.Trim()
            $c48FpIn = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\].*?marker=C011EC48-FP-IN'))
            $c48FpPrepare = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\].*?marker=C011EC48-FP-PREPARE'))
            $c48FpRehome = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\].*?marker=C011EC48-FP-REHOME'))
            $c48FpConsume = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\].*?marker=C011EC48-FP-CONSUME'))
            $c47Calc = @([regex]::Matches($normalized, '\[nativeaot-c011ec47\][^\[]*?marker=C011EC47-RELOC-CALC'))
            $c47Root = @([regex]::Matches($normalized, '\[nativeaot-c011ec47\][^\[]*?marker=C011EC47-ROOT-UPDATE'))
            $invalidC47 = @($c47Calc + $c47Root | Where-Object {
                (Get-MarkerField $_.Value 'base') -eq '0x0000000000000000' -or
                (Get-MarkerField $_.Value 'slot') -eq '0xFFFFFFFFFFFFFF90'
            })
            $debugPath = Join-Path (Split-Path -Parent $run.serial) 'qemu-debug.log'
            $debugPresent = Test-Path -LiteralPath $debugPath -PathType Leaf
            $debugText = if ($debugPresent) { Get-Content -LiteralPath $debugPath -Raw } else { '' }
            $faultMatches = @([regex]::Matches($debugText, '(?im)\bIP=0008:(?<rip>[0-9A-Fa-f]{16})\s+pc=.*?\bCR2=(?<cr2>[0-9A-Fa-f]{16})'))
            $formerFault = @($faultMatches | Where-Object { $_.Groups['cr2'].Value.ToUpperInvariant() -eq 'FFFFFFFFFFFFFF90' })
            $c18Present = $normalized -match 'marker=C011EC18-PREFLIGHT' -and $normalized -match 'marker=C011EC18-FIND-METHOD'
            $c34Present = $normalized -match 'marker=C011EC34-PREFLIGHT'
            $c26Line = [regex]::Match($normalized, 'COMPLETE marker=C011EC26.*?promoteEntries=(?<entries>[0-9A-Fa-f]{8,16})').Value.Trim()
            $c28Present = $normalized -match 'COMPLETE marker=C011EC28'
            $c39Present = $normalized -match 'C37-PHASE collection=00000002 phase=00000008 name=plan-entry' -and
                $normalized -match 'C37-PHASE collection=00000002 phase=00000009 name=plan-return'
            $c40Present = $normalized -match 'COMPLETE marker=C011EC40'
            $c41Present = $normalized -match 'COMPLETE marker=C011EC41'
            $promotedEntries = if (-not [string]::IsNullOrWhiteSpace($c26Line)) {
                [Convert]::ToUInt64((Get-MarkerField $c26Line 'promoteEntries').Substring(2), 16)
            } else { [uint64]0 }
            $decision = & $u 'plannerDecision'
            $compactBranch = & $u 'compactBranch'
            $sweepBranch = & $u 'sweepBranch'
            $completeShape = -not [string]::IsNullOrWhiteSpace($c49CompleteLine)
            $pathShape = if ($decision -eq 1) {
                $compactBranch -eq 1 -and $sweepBranch -eq 0 -and
                    -not [string]::IsNullOrWhiteSpace($compactLine) -and
                    -not [string]::IsNullOrWhiteSpace($relocateLine)
            } elseif ($decision -eq 0) {
                $sweepBranch -eq 1 -and $compactBranch -eq 0 -and
                    -not [string]::IsNullOrWhiteSpace($sweepLine) -and
                    [string]::IsNullOrWhiteSpace($relocateLine)
            } else { $false }
            $requiredFieldsPresent = @(@(
                'preflight','planner','collectionWorkComplete','restartComplete','managedResume',
                'postGcAllocationCount','invariantFailures','sensitiveDiagnosticAllocations',
                'safeStopReason','collectionOrdinal','condemnedGeneration','maximumGeneration',
                'heapIdentity','activeSegment','rootUpdateCallbacks','promotedRoots') |
                Where-Object { $null -eq $fields[$_] })
            $fieldShape = $requiredFieldsPresent.Count -eq 0 -and
                (& $u 'preflight') -eq 1 -and (& $u 'planner') -eq 1 -and
                (& $u 'collectionWorkComplete') -eq 1 -and (& $u 'restartComplete') -eq 1 -and
                (& $u 'managedResume') -eq 1 -and (& $u 'postGcAllocationCount') -eq 8 -and
                (& $u 'invariantFailures') -eq 0 -and (& $u 'sensitiveDiagnosticAllocations') -eq 0 -and
                (& $u 'safeStopReason') -eq 0 -and (& $u 'collectionOrdinal') -eq 2 -and
                (& $u 'condemnedGeneration') -ne 0 -and (& $u 'maximumGeneration') -ne 0 -and
                (& $u 'heapIdentity') -ne 0 -and (& $u 'activeSegment') -ne 0 -and
                (& $u 'rootUpdateCallbacks') -ge 1 -and (& $u 'promotedRoots') -eq 4
            $productionFpRepairStatic = if ($isC011EC50Production) {
                $durableStackPath = Join-Path $nativeAotFpRepairSourceRoot "src\coreclr\nativeaot\Runtime\StackFrameIterator.cpp"
                $durableCoffPath = Join-Path $nativeAotFpRepairSourceRoot "src\coreclr\nativeaot\Runtime\windows\CoffNativeCodeManager.cpp"
                $durableStackText = if (Test-Path -LiteralPath $durableStackPath -PathType Leaf) { Get-Content -LiteralPath $durableStackPath -Raw } else { '' }
                $durableCoffText = if (Test-Path -LiteralPath $durableCoffPath -PathType Leaf) { Get-Content -LiteralPath $durableCoffPath -Raw } else { '' }
                $durableStackText.Contains('m_FramePointer = (PTR_VOID)m_RegDisplay.GetFP();') -and
                    $durableStackText.Contains('m_RegDisplay.pRbp = (PTR_uintptr_t)&m_FramePointer;') -and
                    $durableStackText.Contains('uintptr_t publishedFramePointer') -and
                    $durableStackText.Contains('*m_RegDisplay.pRbp = publishedFramePointer;') -and
                    $durableCoffText.Contains('PTR_uintptr_t callerRbpStorage = pRegisterSet->pRbp;') -and
                    $durableCoffText.Contains('*callerRbpStorage = (uintptr_t)context.Rbp;') -and
                    $durableCoffText.Contains('pRegisterSet->pRbp = callerRbpStorage;')
            } else { $false }
            $c48Baseline = if ($isC011EC50Production) {
                $productionFpRepairStatic -and $formerFault.Count -eq 0 -and $debugPresent -and
                    $c18Present -and $c34Present -and -not [string]::IsNullOrWhiteSpace($c26Line) -and
                    $promotedEntries -eq 4 -and $c28Present
            } else {
                $c48FpIn.Count -gt 0 -and $c48FpPrepare.Count -gt 0 -and
                    $c48FpRehome.Count -gt 0 -and $c48FpConsume.Count -gt 0 -and
                    $invalidC47.Count -eq 0 -and $formerFault.Count -eq 0 -and $debugPresent -and
                    $c18Present -and $c34Present -and -not [string]::IsNullOrWhiteSpace($c26Line) -and
                    $promotedEntries -eq 4 -and $c28Present
            }
            $markersPresent = -not [string]::IsNullOrWhiteSpace($preflightLine) -and
                -not [string]::IsNullOrWhiteSpace($plannerLine) -and
                -not [string]::IsNullOrWhiteSpace($doneLine) -and
                -not [string]::IsNullOrWhiteSpace($restartLine) -and
                -not [string]::IsNullOrWhiteSpace($resumeLine) -and
                (($decision -eq 1 -and -not [string]::IsNullOrWhiteSpace($compactLine)) -or
                 ($decision -eq 0 -and -not [string]::IsNullOrWhiteSpace($sweepLine)))
            $validComplete = $completeShape -and $fieldShape -and $pathShape -and
                $c48Baseline -and $markersPresent -and $c39Present -and $c40Present -and $c41Present
            $runOutcome = if ($validComplete) { 'A' } elseif ($semanticOutcome -in @('B','C')) { $semanticOutcome } else { 'D' }
            $runLevel = switch ($runOutcome) { 'A' { 5 } 'B' { 3 } 'C' { 1 } default { 0 } }
            $c49Runs += [ordered]@{
                name=$run.name; serial=$run.serial; serialSha256=$run.serialSha256
                safeStopMarker=if ($validComplete) { 'C011EC49' } elseif ($completeShape -or -not [string]::IsNullOrWhiteSpace($c49BlockedLine)) { 'C011EC49-BLOCKED' } else { 'C011EC49-TIMEOUT' }
                outcome=$runOutcome; semanticOutcome=$semanticOutcome; successLevel=$runLevel
                markerLine=$c49Line; preflightMarker=$preflightLine; plannerMarker=$plannerLine
                compactMarker=$compactLine; sweepMarker=$sweepLine; relocateMarker=$relocateLine
                collectionDoneMarker=$doneLine; restartMarker=$restartLine; resumeMarker=$resumeLine
                c39=$c39Present; c40=$c40Present; c41=$c41Present; c48=$c48Baseline
                c18=$c18Present; c34=$c34Present; c26=$c26Line; c28=$c28Present
                c47Invalid=$invalidC47.Count; formerFaults=$formerFault.Count; productionFpRepairStatic=$productionFpRepairStatic
                qemuDebugLog=$debugPath; qemuDebugSha256=if ($debugPresent) { Hash-File $debugPath } else { $null }
                fields=$fields; fieldShape=$fieldShape; pathShape=$pathShape; markersPresent=$markersPresent
                c48FpInCount=$c48FpIn.Count; c48FpPrepareCount=$c48FpPrepare.Count
                c48FpRehomeCount=$c48FpRehome.Count; c48FpConsumeCount=$c48FpConsume.Count
                promotedEntries=('0x' + $promotedEntries.ToString('X8')); earlyFailure=if ($validComplete) { $null } else { $run.earlyFailure }
                serialTail=$run.serialTail
            }
        }
        $completeRuns = @($c49Runs | Where-Object { $_.outcome -eq 'A' })
        $allC49Complete = $completeRuns.Count -eq $FreshBootCount
        $signatures = @($completeRuns | ForEach-Object {
            $f = $_.fields
            "$($f.plannerDecision)|$($f.condemnedGeneration)|$($f.collectionOrdinal)|$($f.postGcAllocationCount)|$($_.successLevel)"
        } | Select-Object -Unique)
        $semanticConsistent = $signatures.Count -eq 1
        $c49OutcomeCode = if ($allC49Complete -and $semanticConsistent) { 'A' } elseif (@($c49Runs | Where-Object { $_.outcome -eq 'B' }).Count -gt 0) { 'B' } elseif (@($c49Runs | Where-Object { $_.outcome -eq 'C' }).Count -gt 0) { 'C' } else { 'D' }
        $c49SuccessLevel = switch ($c49OutcomeCode) { 'A' { 5 } 'B' { 3 } 'C' { 1 } default { 0 } }
        $firstC49Run = $c49Runs[0]
        $productionized = $isC011EC50Production
        $resultMarker = if ($productionized) { 'C011EC50' } else { 'C011EC49' }
        $resultDescription = if ($productionized) {
            'productionized NativeAOT FP repair, authentic second-collection continuation, and bounded post-GC allocation result'
        } else {
            'authentic NativeAOT second-collection continuation and bounded post-GC allocation result'
        }
        $manifest = [ordered]@{
            outcome="$c49OutcomeCode / $resultDescription"
            successLevel=$c49SuccessLevel; proofMode=$ProofMode; marker=$resultMarker
            productionized=$productionized
            semanticHarnessRewriteRequired=(-not $productionized)
            durableFpRepair=[ordered]@{ patchApplied=$productionized; sourcePath=if ($productionized) { 'tools/dotnet/runtime-pack/patches/nativeaot-amd64-fp-handoff.patch' } else { $null }; ordinaryRuntimeBuildSwitch=if ($productionized) { '-NativeAotFpRepair' } else { $null } }
            semanticRewriteGuard=[ordered]@{ result=if ($productionized) { 'PASS' } else { 'NOT_APPLICABLE' }; c46SemanticCompileDefine=if ($productionized) { $false } else { $useC011EC46SemanticInjection }; c47SemanticCompileDefine=if ($productionized) { $false } else { $isC011EC47 }; c48SemanticCompileDefine=if ($productionized) { $false } else { $isC011EC48 }; generatedStackFrameIteratorReplacement=$false; durableRuntimeSourceUsed=if ($productionized) { $true } else { $false } }
            runtimePackBuildManifest=if ($productionized) { $RuntimePackManifest } else { $null }
            runtimePackBuildManifestSha256=if ($productionized) { Hash-File $RuntimePackManifest } else { $null }
            lockedRuntimeRoot=if ($productionized -and $lockedRuntimeRootWasProvided) { $LockedRuntimeRoot } else { $null }
            lockedRuntimeCommit=if ($productionized -and $lockedRuntimeRootWasProvided) { $lockedRuntimeActualCommit } else { $null }
            repositoryHead=$repoHead; startingCommittedHead=$startingCommittedHead; startingBranch=$startingBranch
            upstream=$upstream; startingWorktreeStatus=$startingWorktreeStatus; startingDirtyState=$dirtyState
            lockedRuntimeIdentity=[ordered]@{ nativeAot='9.0.0'; architecture='AMD64'; gc='Workstation'; gcInterfaces='5.3 / 2'; sourceCommit=$lockedCommit }
            c49=[ordered]@{ allRunsComplete=$allC49Complete; semanticConsistent=$semanticConsistent; signatures=$signatures; runs=$c49Runs; plannerDecision=$firstC49Run.fields.plannerDecision; condemnedGeneration=$firstC49Run.fields.condemnedGeneration; collectionOrdinal=$firstC49Run.fields.collectionOrdinal; collectionReason=$firstC49Run.fields.collectionReason; maximumGeneration=$firstC49Run.fields.maximumGeneration; heapNumber=$firstC49Run.fields.heapNumber; heapIdentity=$firstC49Run.fields.heapIdentity; activeSegment=$firstC49Run.fields.activeSegment; promotedRoots=$firstC49Run.fields.promotedRoots; rootUpdateCallbacks=$firstC49Run.fields.rootUpdateCallbacks; relocationCallbacks=$firstC49Run.fields.relocationCallbacks; postGcAllocationCount=$firstC49Run.fields.postGcAllocationCount; invariantFailures=$firstC49Run.fields.invariantFailures; sensitiveDiagnosticAllocations=$firstC49Run.fields.sensitiveDiagnosticAllocations; safeStopReason=$firstC49Run.fields.safeStopReason; compactBranch=$firstC49Run.fields.compactBranch; sweepBranch=$firstC49Run.fields.sweepBranch; segmentBefore=$firstC49Run.fields.segmentAllocatedBefore; segmentAfter=$firstC49Run.fields.segmentAllocatedAfter; compactedFrontierBefore=$firstC49Run.fields.compactedFrontierBefore; compactedFrontierAfter=$firstC49Run.fields.compactedFrontierAfter; freeTailStart=$firstC49Run.fields.freeTailStart; freeTailEnd=$firstC49Run.fields.freeTailEnd }
            predecessor=[ordered]@{ C011EC18='PASS / preflight and FindMethodInfo retained'; C011EC26='PASS / promoted roots exactly 4'; C011EC28='PASS / queue closure retained'; C011EC34='PASS / relocation preflight retained'; C011EC47='PASS / no invalid base or former slot'; C011EC48='PASS / FP-IN, FP-PREPARE, FP-REHOME, FP-CONSUME retained' }
            progression=[ordered]@{ planner='authentic C39 planner decision observed'; collection='C49 collection-done, RestartEE, and managed-resume markers'; branch=if ($firstC49Run.fields.plannerDecision -eq '0x00000001') { 'COMPACT' } else { 'SWEEP' }; allocation='bounded C41 eight-allocation continuation'; regression='C18-C48 evidence parsed from each fresh boot' }
            qemu=[ordered]@{ version=$qemuVersion; runCount=$FreshBootCount; proofKernelSha256=$specializedKernelHash; serialSha256=@($c49Runs | ForEach-Object { $_.serialSha256 }); qemuDebugSha256=@($c49Runs | ForEach-Object { $_.qemuDebugSha256 }); evidenceRoot=$runRoot; exactCommandLog=(Join-Path $runRoot 'commands.txt'); runs=$c49Runs }
            payloadHashes=[ordered]@{ proofKernel=$specializedKernelHash; managedPe=(Hash-File $pePath); elf=(Hash-File $elfPath); map=(Hash-File $mapPath); serial=@($c49Runs | ForEach-Object { $_.serialSha256 }) }
            artifactPaths=[ordered]@{ proofKernel=$proofKernelPath; managedPe=$pePath; elf=$elfPath; map=$mapPath }
             regressions=[ordered]@{ C18='PASS; valid manager/FindMethodInfo path retained'; C26='PASS; promoted roots exactly 4'; C28='PASS; mark queue closure retained'; C34='PASS; relocation preflight and root callbacks retained'; C39='PASS; planner decision observed without forcing result'; C40='PASS; compact/sweep production branch observed'; C41='PASS; eight bounded post-GC allocations'; C42='retained historical third-collection lifecycle; not enabled by C49/C50'; C43='retained safety-gate history'; C44='PASS; malformed transition provenance retained'; C45='PASS; reverse-P/Invoke slot provenance retained'; C46=if ($productionized) { 'PASS; durable runtime source check and production execution' } else { 'PASS; REGDISPLAY handoff retained' }; C47=if ($productionized) { 'PASS; no former invalid root base/slot' } else { 'PASS; former invalid root base/slot absent' }; C48=if ($productionized) { 'PASS; durable iterator ownership source check and production execution' } else { 'PASS; iterator FP ownership markers retained' }; semanticHarness=if ($productionized) { 'PASS; C46/C48 semantic rewriting disabled' } else { 'not applicable' }; ordinaryBoot='PASS after finally restoration'; diffCheck='PASS git diff --check' }
             ordinaryRestoration=[ordered]@{ expectedKernelSha256=$normalKernelHash; expectedEspSha256=$normalKernelHash; restoredByFinally=$true; kernelSha256=(Hash-File $kernelPath); espSha256=(Hash-File $espKernelPath) }
             documentation=if ($productionized) { 'docs/dotnet/NATIVEAOT_WORKSTATION_GC_FP_REPAIR_PRODUCTIONIZATION.md' } else { 'docs/dotnet/NATIVEAOT_WORKSTATION_GC_SECOND_COLLECTION_CONTINUATION.md' }; evidenceRoot=$runRoot; manifestPath=$manifestPath
         }
         $manifest | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $manifestPath -Encoding ASCII
         Write-Host "$resultMarker second-collection continuation: $($manifest.outcome) / Level $c49SuccessLevel" -ForegroundColor $(if ($c49SuccessLevel -eq 5) { 'Green' } else { 'Yellow' })
    } elseif ($isC011EC48) {
        if (@($runResults).Count -ne $FreshBootCount) {
            throw "The C011EC48 iterator-FP ownership experiment produced $(@($runResults).Count) runs instead of $FreshBootCount."
        }
        $c48Runs = @()
        foreach ($run in $runResults) {
            $text = Get-Content -LiteralPath $run.serial -Raw
            $normalized = ($text -replace '\[IRQ\] dispatch irq=00\s*', '')
            $normalized = ($normalized -creplace '(?<=[0-9])(?=[a-z])', ' ') -replace '\s+', ' '
            $normalized = $normalized -replace '\b(c\d+)\s+(ec\d+)', '$1$2'
            $normalized = $normalized -replace '\s*=\s*', '='
            $fpInLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\]\s+phase=00000002.*?marker=C011EC48-FP-IN') | ForEach-Object { $_.Value.Trim() })
            $fpPrepareLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\]\s+phase=00000003.*?marker=C011EC48-FP-PREPARE') | ForEach-Object { $_.Value.Trim() })
            $fpRehomeLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\]\s+phase=00000004.*?marker=C011EC48-FP-REHOME') | ForEach-Object { $_.Value.Trim() })
            $consumeGenericLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\]\s+phase=00000005.*?marker=C011EC48-FP-CONSUME') | ForEach-Object { $_.Value.Trim() })
            $consumeDetailLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec48\]\s+fp=.*?marker=C011EC48-FP-CONSUME') | ForEach-Object { $_.Value.Trim() })
            $calcLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec47\]\s+ord=.*?marker=C011EC47-RELOC-CALC') | ForEach-Object { $_.Value.Trim() })
            $rootLines = @([regex]::Matches($normalized, '\[nativeaot-c011ec47\]\s+rootOrdinal=.*?marker=C011EC47-ROOT-UPDATE') | ForEach-Object { $_.Value.Trim() })
            $invalidCalcLines = @($calcLines | Where-Object {
                (Get-MarkerField $_ 'base') -eq '0x0000000000000000' -or
                (Get-MarkerField $_ 'slot') -eq '0xFFFFFFFFFFFFFF90'
            })
            $invalidRootLines = @($rootLines | Where-Object {
                (Get-MarkerField $_ 'base') -eq '0x0000000000000000' -or
                (Get-MarkerField $_ 'slot') -eq '0xFFFFFFFFFFFFFF90'
            })
            $debugPath = Join-Path (Split-Path -Parent $run.serial) 'qemu-debug.log'
            $debugText = if (Test-Path -LiteralPath $debugPath -PathType Leaf) { Get-Content -LiteralPath $debugPath -Raw } else { '' }
            $faultMatches = @([regex]::Matches($debugText, '(?im)\bIP=0008:(?<rip>[0-9A-Fa-f]{16})\s+pc=.*?\bCR2=(?<cr2>[0-9A-Fa-f]{16})'))
            $formerFaultMatches = @($faultMatches | Where-Object { $_.Groups['cr2'].Value -eq 'FFFFFFFFFFFFFF90' })
            if ($formerFaultMatches.Count -gt 0 -or $invalidCalcLines.Count -gt 0 -or $invalidRootLines.Count -gt 0) {
                throw "C011EC48 retained the former null-FP relocation fault in $($run.name)."
            }
            if ($fpInLines.Count -eq 0 -or $fpPrepareLines.Count -eq 0 -or $fpRehomeLines.Count -eq 0 -or
                $consumeGenericLines.Count -eq 0 -or $consumeDetailLines.Count -eq 0 -or $calcLines.Count -eq 0) {
                throw "C011EC48 did not capture the complete FP ownership and reverse-slot sequence in $($run.name)."
            }
            $consumeGeneric = $consumeGenericLines[-1]
            $consumeDetail = $consumeDetailLines[-1]
            $consumePc = Get-MarkerField $consumeGeneric 'pc'
            $consumeSp = Get-MarkerField $consumeGeneric 'sp'
            $fpIn = @($fpInLines | Where-Object {
                (Get-MarkerField $_ 'pc') -eq $consumePc -and (Get-MarkerField $_ 'sp') -eq $consumeSp
            } | Select-Object -Last 1)
            $fpPrepare = @($fpPrepareLines | Where-Object {
                (Get-MarkerField $_ 'pc') -eq $consumePc -and (Get-MarkerField $_ 'sp') -eq $consumeSp
            } | Select-Object -Last 1)
            $fpRehome = @($fpRehomeLines | Where-Object {
                (Get-MarkerField $_ 'pc') -eq $consumePc -and (Get-MarkerField $_ 'sp') -eq $consumeSp
            } | Select-Object -Last 1)
            if ($fpIn.Count -eq 0 -or $fpPrepare.Count -eq 0 -or $fpRehome.Count -eq 0) {
                $fpIn = @($fpInLines | Select-Object -Last 1)
                $fpPrepare = @($fpPrepareLines | Select-Object -Last 1)
                $fpRehome = @($fpRehomeLines | Select-Object -Last 1)
            }
            $fpInLine = $fpIn[-1]
            $fpPrepareLine = $fpPrepare[-1]
            $fpRehomeLine = $fpRehome[-1]
            $incomingFp = Get-MarkerField $fpInLine 'incomingFp'
            $incomingPointer = Get-MarkerField $fpInLine 'incomingP'
            $prepareSource = Get-MarkerField $fpPrepareLine 'sourceFp'
            $prepareAfter = Get-MarkerField $fpPrepareLine 'after'
            $rehomeAfter = Get-MarkerField $fpRehomeLine 'after'
            $rehomePointer = Get-MarkerField $fpRehomeLine 'rehomeP'
            $rehomeGetFp = Get-MarkerField $fpRehomeLine 'getFp'
            $consumeFp = Get-MarkerField $consumeDetail 'fp'
            $consumePointer = Get-MarkerField $consumeDetail 'pRbp'
            $consumeBase = Get-MarkerField $consumeDetail 'base'
            $consumeOffset = Get-MarkerField $consumeDetail 'off'
            $consumeSlot = Get-MarkerField $consumeDetail 'slot'
            $consumeValue = Get-MarkerField $consumeDetail 'value'
            $transitionFrame = Get-MarkerField $consumeDetail 'transition'
            $spValue = [Convert]::ToUInt64($consumeSp.Substring(2), 16)
            $fpValue = [Convert]::ToUInt64($consumeFp.Substring(2), 16)
            $baseValue = [Convert]::ToUInt64($consumeBase.Substring(2), 16)
            $slotValue = [Convert]::ToUInt64($consumeSlot.Substring(2), 16)
            $expectedSlotValue = [uint64]($baseValue - [uint64]0x70)
            $expectedSlot = '0x' + $expectedSlotValue.ToString('X16')
            if ($incomingFp -eq '0x0000000000000000' -or $incomingPointer -eq '0x0000000000000000' -or
                $prepareSource -eq '0x0000000000000000' -or $prepareAfter -eq '0x0000000000000000' -or
                $rehomeAfter -eq '0x0000000000000000' -or $rehomePointer -eq '0x0000000000000000' -or
                $rehomeGetFp -eq '0x0000000000000000' -or $consumeFp -eq '0x0000000000000000' -or
                $consumePointer -eq '0x0000000000000000' -or $consumeBase -eq '0x0000000000000000' -or
                $consumeSlot -eq '0x0000000000000000') {
                throw "C011EC48 observed a null ownership or reverse-slot address in $($run.name)."
            }
            if ($prepareSource -ne $incomingFp -or $prepareAfter -ne $incomingFp -or
                $rehomeAfter -ne $incomingFp -or $rehomeGetFp -ne $incomingFp -or
                $consumeFp -ne $incomingFp -or $consumeBase -ne $incomingFp -or
                $consumeOffset -ne '0xFFFFFFFFFFFFFF90' -or $consumeSlot -ne $expectedSlot -or
                $slotValue -lt $spValue -or $slotValue -gt $fpValue) {
                throw "C011EC48 FP ownership or signed reverse-slot arithmetic invariant failed in $($run.name)."
            }
            $c18Preflight = $normalized -match 'marker=C011EC18-PREFLIGHT'
            $c18FindMethod = $normalized -match 'marker=C011EC18-FIND-METHOD'
            $c34Preflight = $normalized -match 'marker=C011EC34-PREFLIGHT'
            $c26Complete = $normalized -match 'COMPLETE marker=C011EC26'
            $c28Complete = $normalized -match 'COMPLETE marker=C011EC28'
            $promotionMatch = [regex]::Match($normalized, 'COMPLETE marker=C011EC26.*?promoteEntries=(?<entries>[0-9A-Fa-f]{8,16})')
